<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="{{ csrf_token() }}"><title>Retail partners · Crea-Biz EV</title><script src="/theme.js"></script><link rel="stylesheet" href="/platform.css"><link rel="stylesheet" href="/retail-partners.css"><script src="/retail-partners.js" defer></script></head>
<body><main class="retail-wrap"><header><a href="/" data-t="home">Workspace</a><label><span data-t="language">Language</span><select id="language"><option value="en">English</option><option value="ar">العربية</option></select></label><label><span data-t="theme">Theme</span><select id="theme-choice"><option value="system" data-t="system">System</option><option value="light" data-t="light">Light</option><option value="dark" data-t="dark">Dark</option></select></label></header>
<h1 data-t="title">Retail partner governance</h1><p data-t="notice">Internal reviewed partner records. This registry does not enable rewards, money movement or live external fulfillment.</p><p id="status" role="status" aria-live="polite"></p>
<section id="workspace" hidden><form id="search-form"><label><span data-t="search">Reference search</span><input id="search" maxlength="80" dir="auto"></label><button data-t="searchButton">Search</button></form><div id="partners"></div><nav aria-label="Pagination"><button id="previous" data-t="previous">Previous</button><bdi id="page"></bdi><button id="next" data-t="next">Next</button></nav>
<section id="detail" hidden></section>
<details id="editor"><summary data-t="new">Register a retail partner</summary><form id="partner-form">
<input name="partner_id" type="hidden"><input name="expected_revision" type="hidden">
<label><span data-t="reference">Reference</span><input name="reference" pattern="[A-Z0-9][A-Z0-9_-]{2,79}" maxlength="80" required dir="ltr"></label>
<label><span data-t="legalName">Legal name</span><input name="legal_name" maxlength="200" required dir="auto"></label>
<label><span data-t="name">English display name</span><input name="display_name" maxlength="150" required dir="auto"></label>
<label><span data-t="nameAr">Arabic display name</span><input name="display_name_ar" maxlength="150" required dir="rtl"></label>
<label><span data-t="country">Country code</span><input name="country" pattern="[A-Z]{2}" maxlength="2" required dir="ltr"></label>
<label><span data-t="category">Category</span><select name="category"><option value="retail" data-t="retail">Retail</option><option value="hospitality" data-t="hospitality">Hospitality</option><option value="food" data-t="food">Food</option><option value="automotive" data-t="automotive">Automotive</option><option value="services" data-t="services">Services</option></select></label>
<label><span data-t="website">HTTPS website (optional)</span><input name="website" type="url" maxlength="500" dir="ltr"></label>
<label><span data-t="from">Effective from (UTC)</span><input name="effective_from" type="datetime-local" required></label><label><span data-t="until">Expires at (UTC)</span><input name="expires_at" type="datetime-local" required></label>
<label><span data-t="terms">Reviewed contract terms</span><textarea name="terms" required minlength="20" maxlength="10000" dir="auto"></textarea></label><label><span data-t="reason">Decision reason</span><textarea name="reason" minlength="5" maxlength="500" required dir="auto"></textarea></label><button type="submit" data-t="save">Save immutable draft</button><button id="discard" type="button" data-t="discard">Discard editor / new request</button></form></details></section></main></body></html>
